Span.StateHash();sentinel=sentinelBefore;if(overflowSpan.EvaluateTick(skeleton,{2,ExactCycleLimit},boundaryPose,&sentinel)||!Same(boundaryPose,overflowBefore)||std::memcmp(&sentinel,&sentinelBefore,sizeof sentinel)||overflowSpan.StateHash()!=spanState)return Fail("cross-sign span overflow accepted");
